-- Catálogo Agente IA con la estructura de Victoria (22/10/2026): 8 bloques, madres e hijas.
-- Agrega columnas (grupo, nivel, activo, reemplazado_por), madres nuevas y módulos nuevos.
-- Lo duplicado queda activo=false con reemplazado_por: no se borra ninguna fila. ProyectoHoras no se toca.
alter table crm_giwa.catalogo_modulos add column if not exists nivel text;
